import re, pathlib
R=pathlib.Path('.')
def srcs(lib):
    return {str(p):p.read_text(errors='ignore') for p in (R/'core/libs/prx'/lib).rglob('*.cpp') if 'tests' not in p.parts}
def body_of(t,i):
    i=t.find('{',i);d=0
    for j in range(i,len(t)):
        if t[j]=='{':d+=1
        elif t[j]=='}':
            d-=1
            if d==0:return t[i:j+1]
    return ''
DEF=re.compile(r"APS5_VABI\s+(\w+)\s*\(([^;{]*)\)\s*\{")
EXP=re.compile(r'APS5_EXPORT\(\s*"([^"]+)"\s*,\s*(\w+)\s*\)')
def stubs(lib):
    res=[]
    for path,t in srcs(lib).items():
        exp={fn:nid for nid,fn in EXP.findall(t)}
        for m in DEF.finditer(t):
            fn=m.group(1); b=body_of(t,m.start())
            if 'NotImplemented' in b and fn in exp:
                res.append((exp[fn],fn,path,t[:m.start()].count('\n')+1))
    return res
# names from debt
names={}
for lib in ('libSceLibcInternal','libSceFreeTypeOt'):
