        names[nid]=name
libc_all="\n".join(srcs('libc').values())
lci_all="\n".join(srcs('libSceLibcInternal').values())
print("== libSceLibcInternal stubs")
st=stubs('libSceLibcInternal'); print(len(st))
named=0
for nid,fn,path,line in st:
