    if nm.startswith('_ZN') and m:
        m=m[-1];o=m.group(1)[0]+('2' if m.group(1)[1]=='1' else '1')
        cp=nm[:m.start()]+o+nm[m.start()+2:]
        if cp in libc_all: hit.append('libc:'+cp)
        if cp in lci_all: hit.append('lci:'+cp)
    if nm in libc_all: hit.append('libc-same')
    print(f"{nid}\t{nm}\t{path}:{line}\t{' '.join(hit)}")
print("named",named)
print("== libSceFreeTypeOt stubs vs libSceFreeType impl")
ft="\n".join(srcs('libSceFreeType').values())
for nid,fn,path,line in stubs('libSceFreeTypeOt'):
    nm=names.get(nid,fn)
    base=re.sub(r"^sceFreeTypeOt","",fn)
    m=re.search(r"(FT_\w+?)(_nid|$)",fn+" "+nm)
    key=m.group(1) if m else None
    impl=''
    if key:
        mm=re.search(r"APS5_VABI\s+\w*"+re.escape(key)+r"\w*\s*\(",ft)
        if mm:
            b=body_of(ft,mm.start()); impl='FT-impl' if 'NotImplemented' not in b else 'FT-stub'
    print(f"{nid}\t{fn}\t{nm}\t{path}:{line}\t{impl}")
EOF
